import re

def parse_css(css):
    # Remove comments
    css = re.sub(r'/\*.*?\*/', '', css, flags=re.DOTALL)

    rules = []
    # A simple regex to find blocks
    # This works for non-nested rules
    pattern = re.compile(r'([^{}]+)\{([^{}]*)\}')
    for m in pattern.finditer(css):
        selector = m.group(1).strip()
        body = m.group(2).strip()

        # split selector
        selectors = [s.strip() for s in selector.split(',')]

        # split body
        decls = []
        for d in body.split(';'):
            d = d.strip()
            if d:
                parts = d.split(':', 1)
                if len(parts) == 2:
                    decls.append((parts[0].strip(), parts[1].strip()))

        rules.append({
            'selectors': selectors,
            'decls': decls
        })
    return rules

def format_rules(rules, minify=False):
    out = ""
    for i, r in enumerate(rules):
        sel = ', '.join(r['selectors']) if not minify else ','.join(r['selectors']).replace(' > ', '>')
        out += sel + ("{" if minify else " {\n")

        for j, (k, v) in enumerate(r['decls']):
            if minify:
                out += f"{k}:{v}"
                if j < len(r['decls']) - 1:
                    out += ";"
            else:
                out += f"  {k}: {v};\n"

        out += "}" if minify else "}\n"
        if not minify and i < len(rules) - 1:
            out += "\n"

    return out

css = "h1, h2 > h3 { color: red; margin: 10px 20px; }"
print(format_rules(parse_css(css)))
print(format_rules(parse_css(css), minify=True))
EOF
