import re

def parse_css(css):
    css = re.sub(r'/\*.*?\*/', '', css, flags=re.DOTALL)

    tokens = re.finditer(r'([^{}]+)|\{|\}', css)

    ast = []
    stack = [ast]
    current = ""

    for t in tokens:
        val = t.group(0).strip()
        if not val:
            continue

        if val == '{':
            node = {'type': 'rule', 'selector': current.strip(), 'children': []}
            stack[-1].append(node)
            stack.append(node['children'])
            current = ""
        elif val == '}':
            if len(stack) > 1:
                stack.pop()
        else:
            if not current:
                current = val
            else:
                current += " " + val

    # Parse decls
    def traverse(nodes):
        for n in nodes:
            if n.get('children'):
                # Check if it's a property rule or a media rule
                is_media = n['selector'].startswith('@')
                if is_media:
                    traverse(n['children'])
                else:
                    # It's a style rule, children are text?
                    # Actually, my simple parser puts declarations in `current` before `}`!
                    pass
    return ast

css = "@media (min-width: 500px) { body { color: red; } }"
print(parse_css(css))
EOF
