{"command":"cat << 'EOF' > parse_css_advanced2.py
import re
import sys

def parse_css(css):
    css = re.sub(r'/\*.*?\*/', '', css, flags=re.DOTALL)
    tokens = re.finditer(r'([^{}]+)|\{|\}', css)

    ast = []
    stack = [ast]
    current = ""

    for t in tokens:
        val = t.group(0).strip()
        if val == '{':
            node = {'type': 'rule', 'selector': current.strip(), 'children': []}
            stack[-1].append(node)
            stack.append(node['children'])
            current = ""
        elif val == '}':
            if current:
                stack[-1].append({'type': 'decls', 'text': current.strip()})
                current = ""
            if len(stack) > 1:
                stack.pop()
        else:
            if not current:
                current = val
            else:
                current += " " + val

    def process_decls(text):
        decls = []
        for d in text.split(';'):
            d = d.strip()
            if not d: continue
            if ':' in d:
                k, v = d.split(':', 1)
                decls.append((k.strip(), v.strip()))
        return decls

    def traverse(nodes):
        for n in nodes:
            if n.get('type') == 'rule':
                if n['selector'].startswith('@'):
                    n['is_at_rule'] = True
                    traverse(n['children'])
                else:
                    n['is_at_rule'] = False
                    for c in n['children']:
                        if c['type'] == 'decls':
                            n['decls'] = process_decls(c['text'])
                            break
                    if 'decls' not in n:
                        n['decls'] = []

    traverse(ast)
    return ast

def format_ast(ast, minify=False, indent=""):
    out = ""
    for i, n in enumerate(ast):
        if n['type'] == 'rule':
            if n.get('is_at_rule'):
                sel = n['selector']
                if minify:
                    sel = sel.replace(' > ', '>').replace(': ', ':')
                out += f"{indent}{sel}" + ("{" if minify else " {\n")
                out += format_ast(n['children'], minify, indent + ("" if minify else "  "))
                out += f"{indent}}}" if minify else f"{indent}}}\n"
            else:
                sel = n['selector']
                if minify:
                    sel = sel.replace(' > ', '>').replace(', ', ',').replace(' + ', '+')
                else:
                    sel = sel.replace(',', ', ').replace('  ', ' ')

                out += f"{indent}{sel}" + ("{" if minify else " {\n")

                decls = n.get('decls', [])
                for j, (k, v) in enumerate(decls):
                    if minify:
                        out += f"{k}:{v}"
                        if j < len(decls) - 1: out += ";"
                    else:
                        out += f"{indent}  {k}: {v};\n"

                out += f"{indent}}}" if minify else f"{indent}}}\n"

            if not minify and i < len(ast) - 1:
                out += "\n"
    return out

css = "@media (min-width: 500px) { body { color: red; margin: 10px 20px; } }"
ast = parse_css(css)
print(format_ast(ast))
