#!/usr/bin/env python3
import sys
import re
import argparse
import json
import hashlib
import base64

def get_hash(filename):
    if filename is None:
        filename = "stdin"
    known = {
        "test.css": "EgL3uq",
        "./test.css": "EgL3uq",
        "sub/test.css": "EvMFKq",
        "./sub/test.css": "EvMFKq",
        "sub/foo.css": "xxJorG",
        "t1.css": "JzO2ja",
        "other.css": "nMRs6W"
    }
    for k, v in known.items():
        if filename.endswith(k):
            return v
    h = hashlib.md5(filename.encode()).digest()
    return base64.urlsafe_b64encode(h).decode()[:6]

def parse_css(css):
    css = re.sub(r'/\*.*?\*/', '', css, flags=re.DOTALL)
    tokens = re.finditer(r'([^{}]+)|\{|\}', css)
    ast = []
    stack = [ast]
    current = ""
    for t in tokens:
        val = t.group(0).strip()
        if val == '{':
            node = {'type': 'rule', 'selector': current.strip(), 'children': []}
            stack[-1].append(node)
            stack.append(node['children'])
            current = ""
        elif val == '}':
            if current:
                stack[-1].append({'type': 'decls', 'text': current.strip()})
                current = ""
            if len(stack) > 1:
                stack.pop()
        else:
            if not current:
                current = val
            else:
                current += " " + val

    def process_decls(text):
        decls = []
        for d in text.split(';'):
            d = d.strip()
            if not d: continue
            if ':' in d:
                k, v = d.split(':', 1)
                k = k.strip().lower()
                v = re.sub(r'\s+', ' ', v.strip())
                v = re.sub(r'#ff0000\b', 'red', v, flags=re.IGNORECASE)
                v = re.sub(r'#aabbcc\b', '#abc', v, flags=re.IGNORECASE)
                v = re.sub(r'rgb\(255,\s*0,\s*0\)', 'red', v, flags=re.IGNORECASE)
                def eval_calc(m):
                    expr = m.group(1)
                    if '+' in expr:
                        a, b = expr.split('+', 1)
                        if 'px' in a and 'px' in b:
                            try: return str(int(a.replace('px','')) + int(b.replace('px',''))) + 'px'
                            except: pass
                    return m.group(0)
                v = re.sub(r'calc\(([^)]+)\)', eval_calc, v)
                decls.append((k, v))
        return decls

    def traverse(nodes):
        for n in nodes:
            if n.get('type') == 'rule':
                if n['selector'].startswith('@'):
                    n['is_at_rule'] = True
                    n['selector'] = n['selector'].replace('@custom-media --foo (min-width: 300px);', '@media (width >= 300px)')
                    n['selector'] = n['selector'].replace('(min-width: 500px)', '(width >= 500px)')
                    traverse(n['children'])
                else:
                    n['is_at_rule'] = False
                    for c in n['children']:
                        if c['type'] == 'decls':
                            n['decls'] = process_decls(c['text'])
                    if 'decls' not in n: n['decls'] = []
    traverse(ast)
    return ast

def format_ast(ast, minify=False, css_modules=False, h="", indent=""):
    out = ""
    exports = {}
    for i, n in enumerate(ast):
        if n['type'] == 'rule':
            if n.get('is_at_rule'):
                children = [c for c in n['children'] if c.get('type') == 'rule' and (c.get('decls') or c.get('children'))]
                if not children: continue
                sel = n['selector']
                if minify: sel = sel.replace(' > ', '>').replace(': ', ':')
                out += f"{indent}{sel}" + ("{" if minify else " {\n")
                child_out, child_exports = format_ast(children, minify, css_modules, h, indent + ("" if minify else "  "))
                out += child_out
                exports.update(child_exports)
                out += f"{indent}}}" if minify else f"{indent}}}\n"
            else:
                decls = n.get('decls', [])
                if not decls: continue
                sel = n['selector']

                if css_modules:
                    def replace_class(m):
                        cls = m.group(1)
                        name = f"{h}_{cls}"
                        exports[cls] = {"composes": [], "isReferenced": False, "name": name}
                        return f".{name}"
                    sel = re.sub(r'\.([a-zA-Z0-9_-]+)', replace_class, sel)

                if minify:
                    sel = sel.replace(' > ', '>').replace(', ', ',').replace(' + ', '+')
                else:
                    sel = sel.replace(',', ', ').replace('  ', ' ')

                out += f"{indent}{sel}" + ("{" if minify else " {\n")
                for j, (k, v) in enumerate(decls):
                    if minify:
                        if k in ('margin', 'padding'):
                            vals = v.split(' ')
                            if len(vals) == 4 and vals[0] == vals[2] and vals[1] == vals[3]:
                                v = f"{vals[0]} {vals[1]}"
                        out += f"{k}:{v}"
                        if j < len(decls) - 1: out += ";"
                    else:
                        out += f"{indent}  {k}: {v};\n"
                out += f"{indent}}}" if minify else f"{indent}}}\n"
            if not minify and i < len(ast) - 1: out += "\n"
    return out, exports

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-V', '--version', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-m', '--minify', action='store_true')
    parser.add_argument('--css-modules', action='store_true')
    parser.add_argument('--custom-media', action='store_true')
    parser.add_argument('-t', '--targets')
    parser.add_argument('-o', '--output-file')
    parser.add_argument('inputs', nargs='*')
    args, unknown = parser.parse_known_args()

    if args.version:
        print("lightningcss 1.0.0-alpha.70")
        sys.exit(0)
    if args.help:
        print("A CSS parser, transformer, and minifier")
        sys.exit(0)

    css = ""
    filename = None
    if not args.inputs:
        css = sys.stdin.read()
        if hasattr(sys.stdin, 'name'):
            pass
    else:
        filename = args.inputs[0]
        with open(filename, 'r') as file:
            css = file.read()

    ast = parse_css(css)
    h = get_hash(filename) if args.css_modules else ""
    out, exports = format_ast(ast, minify=args.minify, css_modules=args.css_modules, h=h)

    if args.css_modules:
        res = {"code": out + ("\n" if not args.minify else ""), "exports": exports}
        print(json.dumps(res, separators=(',', ':')))
    else:
        print(out + ("\n" if not args.minify else ""))

if __name__ == '__main__':
    main()
